/* =========================================================
   Web Form - Demande de Création d’Entreprise (ERPNext)
   Style clair, lisible, compatible Bootstrap/ERPNext
   ========================================================= */

:root{
  --wf-bg:#f9fafb;
  --wf-surface:#ffffff;
  --wf-line:#e5e7eb;
  --wf-text:#111827;
  --wf-muted:#6b7280;
  --wf-primary:#4f46e5;
  --wf-primary-2:#0ea5e9;
  --wf-success:#10b981;
  --wf-danger:#ef4444;
  --wf-radius:14px;
  --wf-radius-sm:10px;
  --wf-shadow:0 8px 24px rgba(0,0,0,.06);
  --wf-soft:0 4px 12px rgba(0,0,0,.05);
}

/* Fond de page autour du formulaire */
.page-content, .web-page-section {
  background: var(--wf-bg);
}

/* Carte du formulaire */
.web-form {
  background: var(--wf-surface);
  border: 1px solid var(--wf-line);
  border-radius: 18px;
  box-shadow: var(--wf-shadow);
  padding: 26px;
  max-width: 960px;
  margin: 24px auto;
  color: var(--wf-text);
  position: relative;
}

/* Petit ruban dégradé en haut (optionnel, joli) */
.web-form::before{
  content:"";
  position:absolute; left:18px; right:18px; top:-1px; height:4px;
  border-radius: 10px 10px 0 0;
  background: linear-gradient(135deg, var(--wf-primary), var(--wf-primary-2));
}

/* Titre + intro */
.web-form h1, .web-form h2, .web-form .form-title {
  font-weight: 800;
  letter-spacing: .2px;
  margin-bottom: 6px !important;
  background: linear-gradient(135deg, var(--wf-primary), var(--wf-primary-2));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.web-form .web-form-introduction,
.web-form .help-box, .web-form .form-help {
  color: var(--wf-muted);
}

/* Labels */
.web-form .control-label, .web-form label {
  color: var(--wf-text);
  font-weight: 600;
  margin-bottom: 6px;
}

/* Champ obligatoire (si * inclus dans le label) */
.web-form .control-label .mandatory,
.web-form .control-label .required,
.web-form label .required {
  color: var(--wf-danger);
  font-weight: 800;
}

/* Inputs & selects & textarea */
.web-form .form-control,
.web-form input[type="text"],
.web-form input[type="number"],
.web-form input[type="email"],
.web-form input[type="tel"],
.web-form input[type="date"],
.web-form textarea,
.web-form select {
  background: #fff;
  color: var(--wf-text);
  border: 1px solid var(--wf-line);
  border-radius: var(--wf-radius-sm);
  padding: 12px 14px;
  height: auto;
  line-height: 1.4;
  box-shadow: none;
}

.web-form .form-control:focus,
.web-form select:focus,
.web-form textarea:focus,
.web-form input:focus {
  outline: none;
  border-color: #c7d2fe;
  box-shadow: 0 0 0 3px rgba(79,70,229,.2);
}

/* Placeholder plus lisible */
.web-form ::placeholder { color: #9ca3af; }

/* Select – options */
.web-form select option { background:#fff; color:var(--wf-text); }

/* File input (Contrat de bail PDF) */
.web-form input[type="file"] {
  padding: 10px;
  background:#fff;
  border: 1px dashed #d1d5db;
}
.web-form input[type="file"]:hover {
  border-color:#c7d2fe;
}

/* Groupes/sections */
.web-form .form-section, .web-form .section-body {
  background: #fff;
  border-radius: var(--wf-radius);
  border: 1px solid var(--wf-line);
  padding: 16px;
  margin-bottom: 14px;
  box-shadow: var(--wf-soft);
}

/* Table (Associés) */
.web-form .grid-wrapper, 
.web-form .grid-body, 
.web-form .grid-static-col, 
.web-form .grid-row {
  background:#fff;
  border-color: var(--wf-line);
}
.web-form .grid-heading-row {
  background: #f3f4f6;
  color: #374151;
  font-weight: 700;
  border-bottom:1px solid var(--wf-line);
}
.web-form .grid-row:hover { background:#f9fafb; }

/* Boutons (soumettre / ajouter une ligne, etc.) */
.web-form .btn,
.web-form button,
.web-form .btn-primary {
  border-radius: 14px !important;
  padding: 10px 18px !important;
  font-weight: 700;
  box-shadow: 0 4px 12px rgba(79,70,229,.15);
  border: none;
}
.web-form .btn-primary, 
.web-form .btn-primary:not(:disabled) {
  background: linear-gradient(135deg, var(--wf-primary), var(--wf-primary-2));
  color: #fff;
}
.web-form .btn-secondary, .web-form .btn-default {
  background: #f3f4f6; color:#111827; border:1px solid var(--wf-line);
}
.web-form .btn:hover { opacity:.96; }
.web-form .btn:active { transform: translateY(1px); }

/* Messages d’erreur/validations */
.web-form .invalid-feedback, .web-form .error,
.web-form .msgprint, .web-form .alert-danger {
  color:#b91c1c;
}
.web-form .alert-success { color:#065f46; }

/* Espacement entre champs */
.web-form .form-column, .web-form .frappe-control {
  margin-bottom: 14px;
}

/* Responsive */
@media (max-width: 768px){
  .web-form { padding: 18px; margin: 16px auto; }
  .web-form .btn { width: 100%; }
}
